# Guides for blackoutsos.com. Short, practical, UK, checked against official advice.
# Structure: sections = (label, unit, heading, items). label/unit are the big number and its caption.

GUIDES = [
dict(slug="power-cut-the-first-hour", cat="Power", mins=6, title="Power cut:<br>the first hour", plain="Power cut: the first hour",
    summary="Call 105. Fridge shut. Torch, not candles. Never a barbecue indoors.",
    lede="Most UK power cuts are over in under an hour. The first hour is also when people hurt themselves: candles, barbecues indoors, a dark staircase. Here is the order to do things in, with what to take from your bag at each step.",
    checked="Checked against Energy Networks Association and gov.uk guidance",
    sections=[
        ("0–5", "minutes", "Light, then find out if it's just you", [
            "Get the head torch from the lid pocket of your bag before you move around. Put it on. Hands free, no candle.",
            "Look out of the window. If the street lights and neighbours are dark, it's the network. If it's only you, check your consumer unit for a tripped switch before calling anyone.",
            "Call <strong>105</strong>. It's free from any phone and connects you to your local network operator, who will tell you what they know and when they expect power back. Their website has a live map if your phone has signal.",
            "Switch off anything that was on and could be dangerous when the power returns: the hob, an iron, a heater, the oven. Leave one light switched on so you know when it's back."]),
        ("5–30", "minutes", "Protect the food, the phone and the people", [
            "Keep the fridge and freezer shut. A closed fridge holds a safe temperature for around four hours; a full, closed freezer for around 48 hours, a half-full one for 24. Every opening costs you time.",
            "Put your phone on low-power mode and plug it into the power bank from the lid pocket. Text, don't call; texts get through on a weak signal.",
            "Wind the radio for two minutes and find your local station. If the cut is wide, that's where the updates will be.",
            "Check on anyone nearby who is older, alone, or uses a medical device. If that's someone in your house, register with your network's Priority Services Register when this is over; it's free and they'll call you first next time.",
            "If it's cold, pick one room, shut the doors, and open the grey pouch: hand warmers and a foil blanket are worth more than a draughty whole house."]),
        ("30–60", "minutes", "Decide whether this is an evening or a night", [
            "If you live in a flat, your water may be pumped. Fill the kettle, a couple of bottles and the bath while the pressure lasts. You have purification tablets in the olive pouch if you need to treat it later.",
            "Find the cash in your document pouch. Card machines and cash machines go down with the power; the shop that stays open is the one that takes notes.",
            "Medication: most insulin is fine out of the fridge for up to 28 days, but check your own leaflet. If someone depends on a powered device such as oxygen or a ventilator and you have no backup, that is a 999 call, not a wait.",
            "Agree the plan for the night: who sleeps where, who checks the hob is off, where the torch lives. If a vulnerable person in the house can't be kept warm, or the network says it's going to be a long one, this is when the Unit bag goes in the car and you go to family.",
            "Open the comfort pack. Glucose, a hot drink from the flask if you have one, and a game of cards do more for morale than another hour of staring at a phone."])],
    never=("Never", "Never run a generator, barbecue, camping stove or patio heater indoors or in a garage, even with the door open. Carbon monoxide has no smell and kills people in UK power cuts every winter. Never leave a candle burning in a room you've left. Your torch and glow sticks exist so you don't have to."),
    after=("When it comes back", "Check the freezer: if food is still frozen hard, it's fine; if it has thawed, cook it or bin it. Recharge the power bank the same day and put it back in the lid; that's the thing people forget. Reset clocks, restart the boiler, and write down what you wished you'd had. Then tell us, and we'll put it in the next bag."),
    frombag=[("#ededed", "Lid pocket:", "head torch, power bank and cable, wind-up radio, glow sticks"), ("#6b6b6b", "Grey pouch:", "hand warmers, foil blanket, hat and gloves"), ("#5c6a3a", "Olive pouch:", "water, purification tablets, comfort pack"), ("#2a2a2a", "Document pouch:", "cash, contacts card with 105 and your network on it")],
    numbers=[("Power cut", "105"), ("Smell gas", "0800 111 999"), ("Urgent health", "111"), ("Life at risk", "999")],
    cta=("operator", "The Operator, £199", "Everything this guide reaches for, in four pouches and a lid."),
    next=["water-treating-storing-rationing", "medication-and-medical-devices", "heatwave-and-cold-snap"],
    sources=[("Power Cut 105", "https://www.powercut105.com/"), ("Priority Services Register, Ofgem", "https://www.ofgem.gov.uk/information-consumers/energy-advice-households/getting-extra-help-priority-services-register"), ("Carbon monoxide poisoning, NHS", "https://www.nhs.uk/conditions/carbon-monoxide-poisoning/"), ("Prepare: get ready for emergencies, gov.uk", "https://prepare.campaign.gov.uk/")]),

dict(slug="flooding-before-during-after", cat="Weather", mins=9, title="Flooding:<br>before, during, after", plain="Flooding: before, during, after",
    summary="Floodline, the 30 cm rule for cars, what to move upstairs, and why flood water is never safe to wade.",
    lede="Flooding is the UK's most common emergency and the one that gives the most warning. Sign up once, and the Environment Agency will text you days ahead. Then the job is moving the right things up and the right people out, early, before the water decides for you.",
    checked="Checked against Environment Agency and gov.uk guidance",
    sections=[
        ("Before", "today", "Know your risk and get the warning", [
            "Check your address at gov.uk's flood risk service, and sign up for free flood warnings by text, email or phone. A flood alert means be prepared; a flood warning means act now; a severe flood warning means danger to life.",
            "Agree where the family goes if you have to leave: a relative on higher ground, not a rest centre you have never seen. Write it on the family plan card in the Unit.",
            "Find out now how to turn off the gas, electricity and water. Label the switches.",
            "Put copies of documents, photos and insurance details in the document pouch. Photograph every room while it's dry; the insurer will ask."]),
        ("During", "the warning", "Move things up, people out, early", [
            "When the warning comes, move valuables, medicines and the children's things upstairs or onto high shelves. Put the Unit and the Operators by the door you will leave by.",
            "Turn off the gas and electricity at the mains if water is coming in. Do not touch switches with wet hands or while standing in water.",
            "Leave early, in daylight, by the route you planned. If you are told to evacuate, go. If you wait for the water, you lose the car and the choice.",
            "Never walk or drive through flood water. Fifteen centimetres of fast-flowing water can knock an adult over; thirty centimetres will float a car. Manhole covers lift; you cannot see the hole.",
            "Keep the pets in their carriers from the moment the warning comes, and take them with you. Open the Scout bag and clip the lead on before you open the door."]),
        ("After", "the water drops", "Treat everything it touched as contaminated", [
            "Flood water carries sewage, fuel and chemicals. Wear the nitrile gloves and a mask from the green pouch when you go back in, and wash your hands with the sanitiser before you eat anything.",
            "Do not switch the electricity back on until an electrician has checked it. Do not use the gas boiler until it has been checked.",
            "Throw away any food that touched flood water, including sealed tins with damaged seams. Treat tap water as unsafe until the water company says otherwise: boil it, or use the tablets.",
            "Call the insurer before you throw anything away, photograph everything, and keep the receipts. Ask the council about the recovery scheme for your area.",
            "Ventilate and dry the house slowly; heaters on full in a wet house grow mould. Ask for help: the stress of a flood lasts longer than the water."])],
    never=("Never", "Never drive into flood water, even if the car in front made it. Most flood deaths in the UK happen in vehicles. Turn around."),
    after=None,
    frombag=[("#5c6a3a", "Olive pouch:", "water and purification tablets, for when the taps are off"), ("#2f7d4a", "Green pouch:", "nitrile gloves and masks for the clean-up"), ("#2a2a2a", "Document pouch:", "insurance details, document copies, cash"), ("#6b6b6b", "Grey pouch:", "poncho and bivvy bag for the wait on higher ground")],
    numbers=[("Floodline, 24 hours", "0345 988 1188"), ("Life at risk", "999"), ("Power cut", "105"), ("Smell gas", "0800 111 999")],
    cta=("unit", "The Unit, £449", "The family's leave-by-car bag: water for four, filter, shelter, family first aid."),
    next=["the-family-meeting-point", "water-treating-storing-rationing", "pets-in-an-emergency"],
    sources=[("Sign up for flood warnings, gov.uk", "https://www.gov.uk/sign-up-for-flood-warnings"), ("Check for flooding, gov.uk", "https://www.gov.uk/check-flooding"), ("Prepare: get ready for emergencies, gov.uk", "https://prepare.campaign.gov.uk/")]),

dict(slug="storms-and-high-wind", cat="Weather", mins=5, title="Storms and<br>high wind", plain="Storms and high wind",
    summary="Amber and red warnings, what to tie down, and when staying put is the right call.",
    lede="A named storm gives you a day or two of notice and the Met Office tells you how bad in three colours. Yellow: be aware. Amber: be prepared, change your plans. Red: danger to life, stay in. The bag matters for the hours after, when the power is off and the roads are blocked.",
    checked="Checked against Met Office and gov.uk guidance",
    sections=[
        ("Before", "the warning", "The afternoon before", [
            "Read the warning itself, not the headline. The Met Office map shows the area and the hours; the text says whether it's wind, rain or both, and what to expect: power cuts, travel disruption, flying debris.",
            "Bring in or tie down anything that can fly: bins, trampolines, garden furniture, the ladder. Park the car away from trees and walls. Close and lock windows and doors.",
            "Charge everything, including the power bank in the lid, and fill the car with fuel while the pumps still work. Draw some cash.",
            "Check on anyone nearby who lives alone, and agree who will check in on whom. Move the Operators to the hall and the Unit to the car."]),
        ("During", "the storm", "Stay in, stay away from glass", [
            "If the warning is red, stay in and keep the family away from windows. Use the inner rooms and the stairs; sleep downstairs if the roof is old.",
            "Do not go out to check on the roof, the fence or the car. Flying tiles and falling branches kill people who went to look.",
            "If the power goes, follow the power-cut guide: torch on, 105, fridge shut, one warm room. Keep the radio on for the local station.",
            "If you must travel, don't use exposed roads, bridges or the coast. Fallen power lines are live: stay well back and call 105."]),
        ("After", "the all-clear", "Carefully", [
            "Wait for the warning to end before you go out. Look up before you look down: loose tiles, hanging branches and damaged lines are the danger now.",
            "Photograph any damage before you touch it, and call the insurer. Do not climb on a roof; that is what the insurer's contractor is for.",
            "Check on neighbours, then help clear the street only where it is safe. Report fallen lines to 105 and blocked roads to the council.",
            "Refill what you used: the power bank, the comfort pack, the cash. Tell us what you wished you'd had."])],
    never=("Never", "Never shelter under a tree or next to a wall in high wind, and never drive through standing water to get home faster. The storm is finite; the decision to wait it out is the one you won't regret."),
    after=None,
    frombag=[("#ededed", "Lid pocket:", "head torch, radio, power bank, glow sticks for the stairs"), ("#6b6b6b", "Grey pouch:", "poncho, hand warmers, foil blanket"), ("#5c6a3a", "Olive pouch:", "water and the comfort pack"), ("#2a2a2a", "Black pouch:", "duct tape and paracord for a broken window, in the morning")],
    numbers=[("Power cut or fallen line", "105"), ("Life at risk", "999"), ("Floodline", "0345 988 1188"), ("Smell gas", "0800 111 999")],
    cta=("operator", "The Operator, £199", "Light, warmth, radio and power for the night after the storm."),
    next=["power-cut-the-first-hour", "flooding-before-during-after", "the-family-meeting-point"],
    sources=[("UK weather warnings, Met Office", "https://www.metoffice.gov.uk/weather/warnings-and-advice/uk-warnings"), ("Power Cut 105", "https://www.powercut105.com/"), ("Prepare: get ready for emergencies, gov.uk", "https://prepare.campaign.gov.uk/")]),

dict(slug="cyber-outage-cards-cash-and-comms", cat="Planning", mins=6, title="Cyber outage:<br>cards, cash and comms", plain="Cyber outage: cards, cash and comms",
    summary="When the tills, the apps and the signal go. Why £50 in small notes and a printed contacts card matter.",
    lede="The newest emergency is the one with no weather. A bank's app down for a day, a supermarket's tills offline, a mobile network out across a region. Nothing is broken in your house, and yet you cannot buy milk or call your mother. The fix is paper and coins.",
    checked="Checked against National Cyber Security Centre and gov.uk guidance",
    sections=[
        ("Today", "once", "Twenty minutes of paper", [
            "Print a contacts card: family, the school, the GP, the vet, your bank's phone number, your insurer, the out-of-area contact. One copy in each bag's document pouch, one on the fridge. Phones die and apps need a signal; paper doesn't.",
            "Keep £50 to £100 in small notes and coins in the document pouch. In an outage the shop that stays open is the one that takes cash, and nobody can change a fifty.",
            "Keep a paper map of your area in the bag. Satnav and maps apps stop with the signal.",
            "Know what a scam looks like in a crisis. Outages are followed by texts and calls pretending to be your bank. Your bank will never ask you to move money to a 'safe account'."]),
        ("During", "the outage", "Slow down, go analogue", [
            "Check whether it's you, your provider or everyone: the radio in the lid will tell you if it's national. Don't reinstall apps or reset passwords in a panic; that's when mistakes happen.",
            "Pay cash, keep receipts, and buy only what you need for two days. Panic-buying is what turns an outage into a shortage.",
            "If mobile networks are down, texts often get through before calls, and Wi-Fi calling may still work at home. Agree a check-in time with the family rather than trying every ten minutes.",
            "For an emergency, 999 works from any network, including one you aren't a customer of, and from a phone with no SIM."]),
        ("After", "it's back", "Check before you trust", [
            "Check your bank statements for the days around the outage, and your email for password-reset messages you didn't ask for.",
            "Change the password on anything that behaved strangely, and turn on two-step verification if you hadn't.",
            "Top the cash back up. Replace the receipts in the pouch with the contacts card. Done."])],
    never=("Never", "Never give a one-time code, a PIN or a password to anyone who calls you, however urgent they sound and whatever number they appear to call from. Hang up, wait five minutes, and call the number on the back of your card."),
    after=None,
    frombag=[("#2a2a2a", "Document pouch:", "cash, contacts card, paper map"), ("#ededed", "Lid pocket:", "wind-up radio for the national picture, power bank"), ("#5c6a3a", "Olive pouch:", "two days of food and water so you don't need the shop")],
    numbers=[("Life at risk, any network", "999"), ("Non-emergency police", "101"), ("Your bank", "on the back of your card"), ("Scam advice", "ncsc.gov.uk")],
    cta=("operator", "The Operator, £199", "Document pouch, radio and two days of not needing the shops."),
    next=["the-family-meeting-point", "power-cut-the-first-hour", "the-72-hour-list-explained"],
    sources=[("National Cyber Security Centre", "https://www.ncsc.gov.uk/"), ("Prepare: get ready for emergencies, gov.uk", "https://prepare.campaign.gov.uk/"), ("Emergency Alerts, gov.uk", "https://www.gov.uk/alerts")]),

dict(slug="water-treating-storing-rationing", cat="Water and food", mins=7, title="Water: treating,<br>storing, rationing", plain="Water: treating, storing, rationing",
    summary="Tablets, boiling, the bath trick, and how much a person actually needs a day.",
    lede="You can go three days without water and feel terrible after one. The bag carries the first day and the means to make fifty more litres safe; your home should hold the rest. Here is how much, where to keep it, and how to make bad water drinkable.",
    checked="Checked against gov.uk Prepare and Drinking Water Inspectorate guidance",
    sections=[
        ("How much", "to store", "Three days, per person, plus the extras", [
            "For drinking alone, an adult needs about 2.5 to 3 litres a day; the government's guidance calls 10 litres a day per person 'most comfortable' once cooking and washing are included. Three days for a family of four is 30 litres to drink, and far more to be comfortable.",
            "Store bottled water somewhere cool and dark, and rotate it: write the date on the bottles, and use the oldest for the garden when the year is up.",
            "Add water for pets, and for a baby's formula if you use powder. Ready-to-feed formula needs none, which is why it's in the Cub.",
            "The bag's 500 ml pouches are five-year, foil-sealed water for the first day on the move. They are not the store; they are the walk to it."]),
        ("When", "the taps stop", "Fill what you can, then treat what you must", [
            "The moment you hear of a problem, fill the kettle, every bottle and the bath. Bath water is for flushing and washing; the kettle and bottles are for drinking.",
            "Boiling is the surest method: bring water to a rolling boil for one minute, let it cool, and keep it covered. It kills bacteria, viruses and parasites. It does not remove chemicals.",
            "Tablets: one chlorine tablet per litre, wait the time on the packet (usually 30 minutes), longer if the water is cold. Filter cloudy water through a clean cloth first, or the tablet cannot do its job.",
            "The Unit's squeeze filter removes bacteria and parasites down to 0.1 micron from stream, pond or rain water. Add a tablet afterwards for viruses, or boil. Never drink flood water, however it has been treated: it carries fuel and sewage."]),
        ("Rationing", "if it comes to it", "Drink, don't sip, and cut the work", [
            "Drink a proper glass when you are thirsty rather than sips all day; sipping doesn't save water, it makes you miserable. Eat the ration bar with water, not without.",
            "Cut the things that use water: no washing up (use the wipes), no cooking that needs water, cool rooms not hot ones. Children and older people dehydrate fastest; they get water first.",
            "Signs of dehydration: dark urine, headache, dizziness, confusion. Confusion in an older person in hot weather is a 111 call, or 999 if they cannot keep fluids down.",
            "Rain is clean until it touches the roof. A tarp and the foldable container from the Unit will catch litres in a British hour. Treat it anyway."])],
    never=("Never", "Never use pool chemicals, neat bleach or petrol-station screenwash to treat drinking water. Use the tablets, the filter or the kettle, in that order of convenience, and boiling if in doubt."),
    after=None,
    frombag=[("#5c6a3a", "Olive pouch:", "water pouches, purification tablets, bottle"), ("#2a2a2a", "Black pouch:", "wipes, so washing up stops"), ("Unit cube A", "Unit:", "squeeze filter, 10-litre container, 6 pouches")],
    numbers=[("Urgent health", "111"), ("Life at risk", "999"), ("Your water company", "on your bill"), ("Floodline", "0345 988 1188")],
    cta=("unit", "The Unit, £449", "Six pouches, a 0.1-micron filter, 100 tablets and a 10-litre container for the family."),
    next=["the-72-hour-list-explained", "flooding-before-during-after", "heatwave-and-cold-snap"],
    sources=[("Prepare: get ready for emergencies, gov.uk", "https://prepare.campaign.gov.uk/"), ("Drinking Water Inspectorate", "https://www.dwi.gov.uk/"), ("Dehydration, NHS", "https://www.nhs.uk/conditions/dehydration/")]),

dict(slug="leaving-the-house-with-a-baby", cat="Family", mins=7, title="Leaving the house<br>with a baby", plain="Leaving the house with a baby",
    summary="Ready-to-feed formula, sterile teats, the wrap, the pram clips, and who carries what.",
    lede="Everything about an emergency is harder with a baby, and everything about a baby is easier with a plan. Feeding without a kettle, keeping them warm, keeping your hands free, and what goes where on the way out of the door.",
    checked="Checked against NHS infant feeding guidance",
    sections=[
        ("Feeding", "without power", "Sterile until opened", [
            "Ready-to-feed formula in cartons is sterile and needs no water, no kettle and no fridge until it is opened. Powdered formula is not sterile and must be made with water of at least 70 degrees, which you may not have. That is why the Cub carries cartons.",
            "Use a fresh sealed teat for each feed and throw it away. The one bottle is sterilised between feeds with a cold-water sterilising tablet in a bag of water: follow the tablet's instructions, and the NHS advice to leave equipment in solution for at least 30 minutes.",
            "An opened carton goes in the fridge if there is one and is used within 24 hours; with no fridge, finish it or bin it. Never keep a half-drunk feed for later.",
            "If you breastfeed, keep going; it is the safest feed there is. Drink the water in the Cub's olive pouch, eat, and rest when the baby does. The cartons are the backup you hope not to open."]),
        ("Warmth", "and sleep", "A baby cannot tell you they're cold", [
            "Dress the baby in layers and a hat, and use the fleece blanket. The foil blanket goes over the fleece, never against the skin, and never over the face.",
            "Your body is the best heater: the wrap carrier keeps the baby warm against you and your hands free for the door, the pram and the other children.",
            "Check the back of the neck, not the hands, to tell if a baby is warm enough. Sweaty means too hot; cool means add a layer.",
            "Safe sleep rules do not change in an emergency: on their back, on a flat firm surface, no loose bedding over the head. The changing mat on the floor beats a sofa cushion."]),
        ("The door", "and the walk", "Who carries what", [
            "Baby in the wrap on your front, Cub on your back, or Cub clipped onto the pram handle. If the other adult has an Operator, the Cub clips onto its front and you carry the baby only.",
            "The feeding-plan card in the Cub's document sleeve says how your baby takes a feed, how much and how often, for whoever is holding them when you are not.",
            "Nappies first, food second: a baby can miss a feed by an hour; a wet, cold baby can't wait. Change them before you leave, and again at the first stop.",
            "Tell the rest centre or the relative you are coming with a baby. Ask for a quiet corner, somewhere to lie the mat, and water."])],
    never=("Never", "Never make up powdered formula with unboiled or cooled water in an emergency, and never water a feed down to make it last. A smaller sterile feed is safe; a diluted or unsterile one is not."),
    after=None,
    frombag=[("#5c6a3a", "Olive pouch:", "formula cartons, bottle, sealed teats, sterilising tablets, water"), ("#2a2a2a", "Black pouch:", "nappies, wipes, bags, cream"), ("#6b6b6b", "Grey pouch:", "wrap carrier, blankets, hat and socks, muslins"), ("#2f7d4a", "Green pouch:", "thermometer, saline, your medicines pouch")],
    numbers=[("Urgent health", "111"), ("Life at risk", "999"), ("Your health visitor", "on the feeding card"), ("Power cut", "105")],
    cta=("cub", "The Cub, £149", "Three days for a baby, in three stages. Clips onto a pram or an Operator."),
    next=["teaching-your-child-the-bag", "the-family-meeting-point", "power-cut-the-first-hour"],
    sources=[("Making up baby formula, NHS", "https://www.nhs.uk/conditions/baby/breastfeeding-and-bottle-feeding/bottle-feeding/making-up-baby-formula/"), ("Sterilising baby bottles, NHS", "https://www.nhs.uk/conditions/baby/breastfeeding-and-bottle-feeding/bottle-feeding/sterilising-baby-bottles/"), ("Prepare: get ready for emergencies, gov.uk", "https://prepare.campaign.gov.uk/")]),

dict(slug="teaching-your-child-the-bag", cat="Family", mins=5, title="Teaching your<br>child the bag", plain="Teaching your child the bag",
    summary="A ten-minute game that means a seven-year-old can find the whistle and the torch in the dark.",
    lede="A child who has opened the bag before is calm when it matters. A child who hasn't is frightened of a black rucksack. Ten minutes, three rules and one game, repeated every six months when you check the batteries.",
    checked="Written with the Recruit's 'what to do' card",
    sections=[
        ("The rules", "three of them", "Stay. Blow. Show.", [
            "<strong>Stay with your adult.</strong> If you get separated, stay where you are, in the open, and let the adults come to you. Moving makes you harder to find.",
            "<strong>Blow the whistle.</strong> Three blasts, a pause, three more. The whistle is louder than a shout and works when a voice is gone. It is in the buckle on your chest and on the lanyard in the lid.",
            "<strong>Show the card.</strong> The card in the window has your name, our number and a photo of us. Show it to a police officer, a firefighter, or a grown-up with children, and ask them to call the number.",
            "Say the rules back to me. Now say them with the lights off."]),
        ("The game", "ten minutes", "Find it in the dark", [
            "Lights off, curtains shut. 'Find the torch.' The lid pocket, every time. Put it on. Now the whistle. Now the foil blanket, in the grey pouch. Make it a race against the stopwatch and let them win.",
            "'Which pouch is water?' Olive. 'Which is plasters?' Green. The colours are the same in every bag in the house, so they learn once.",
            "Let them put the comfort toy in its pouch themselves, and write their name on the wristband. It's their bag now.",
            "Pack it with them, not for them. A child who packed the bag knows what's in it."]),
        ("Every six", "months", "When the clocks change", [
            "Check the torch and swap the glow sticks. Update the number on the wristband if it changed, and the photo if the child has grown out of it.",
            "Play the game again, lights off. It takes five minutes the second time.",
            "Walk the route to the meeting point together and let them lead. Then let them tell the next adult what the bag is for.",
            "Older children can learn the family's out-of-area contact number by heart. Make it the one number they know."])],
    never=("Never", "Never frighten a child into the bag. The language is 'if the lights go out' and 'if we have to go to Grandma's in a hurry', not disaster. Confidence is the thing you are packing."),
    after=None,
    frombag=[("#ededed", "Lid pocket:", "head torch, glow sticks, whistle, the 'what to do' card"), ("#6b6b6b", "Grey pouch:", "foil blanket, poncho, hat, the comfort toy"), ("#D0202E", "Name window:", "the wristband and the family photo card")],
    numbers=[("Three blasts, pause, three", "the whistle"), ("Life at risk", "999"), ("Non-emergency police", "101"), ("Your out-of-area contact", "learn it")],
    cta=("recruit", "The Recruit, £89", "A child's own bag: light, warmth, a whistle, an ID wristband. No blades, no fire."),
    next=["the-family-meeting-point", "leaving-the-house-with-a-baby", "pets-in-an-emergency"],
    sources=[("Prepare: get ready for emergencies, gov.uk", "https://prepare.campaign.gov.uk/"), ("Emergency Alerts, gov.uk", "https://www.gov.uk/alerts")]),

dict(slug="medication-and-medical-devices", cat="Health", mins=6, title="Medication and<br>medical devices", plain="Medication and medical devices",
    summary="Insulin without a fridge, CPAP without power, and the one conversation to have with your pharmacist now.",
    lede="The bag has a medication pouch and it is empty, because only you know what goes in it. This guide is the conversation to have with your pharmacist this week, so that a power cut or a night away is a nuisance and not a crisis.",
    checked="Checked against NHS and Diabetes UK guidance; always follow your own prescriber",
    sections=[
        ("This week", "once", "The pharmacist conversation", [
            "Ask for a printed list of everything you take, with doses and times. One copy in the medication pouch, one with the contacts card. In an emergency, this is what the paramedic reads.",
            "Ask how each medicine copes without a fridge, and for how long. Most insulin keeps for up to 28 days at room temperature once out of the fridge, below 25 degrees, but check your own leaflet; some medicines spoil faster, some are fine for years.",
            "Ask about keeping a few days in hand. Many pharmacies can help you build a small buffer so a missed delivery or a closed shop doesn't mean a missed dose. Rotate it: oldest first.",
            "Register with your energy network's Priority Services Register if anyone in the house depends on a powered device, insulin, or a stairlift. It's free, and they call you first in a cut."]),
        ("Without", "power", "Devices that need the mains", [
            "Oxygen concentrators, ventilators and home dialysis: your supplier will have told you what the backup is. If they haven't, ring them this week. If a device stops and you have no backup, it is 999, not a wait.",
            "CPAP: a night without it is unpleasant and, for most people, not dangerous, but talk to your sleep clinic now about a battery pack if you are in the group for whom it matters.",
            "Powered wheelchairs and stairlifts: know where the manual release is, and where the person sleeps if upstairs is out of reach.",
            "Fridge medicines: keep the fridge shut; four hours is usually fine. Beyond that, a cool bag with the frozen pouches from the freezer, and the leaflet's temperature rules."]),
        ("Away", "from home", "If you have to leave", [
            "The medication pouch travels in the Operator's green pouch, with the printed list. Take the whole box, not loose tablets, so the label travels too.",
            "Keep the pill organiser filled for the week ahead; it is the thing that keeps a routine when everything else has gone.",
            "Tell whoever you are staying with, or the rest centre, what you take and when. Ask them to remind you; stress makes people forget doses.",
            "If you run out, a pharmacist can often provide an emergency supply of a regular medicine without a prescription. Ask; don't go without."])],
    never=("Never", "Never stop a prescribed medicine because you are worried about running out; halve the worry, not the dose. Ring 111 for advice, or your pharmacist, before you change anything."),
    after=None,
    frombag=[("#2f7d4a", "Green pouch:", "first aid kit, your medication pouch and pill organiser, masks"), ("#2a2a2a", "Document pouch:", "the printed medicines list, contacts card"), ("#ededed", "Lid pocket:", "torch and power bank for a device that charges by USB")],
    numbers=[("Urgent health", "111"), ("Life at risk", "999"), ("Power cut", "105"), ("Your pharmacy", "on the list")],
    cta=("operator", "The Operator, £199", "A BS 8599-1 first aid kit, a labelled medication pouch and a pill organiser, waiting for you."),
    next=["power-cut-the-first-hour", "heatwave-and-cold-snap", "the-72-hour-list-explained"],
    sources=[("Diabetes UK", "https://www.diabetes.org.uk/"), ("Priority Services Register, Ofgem", "https://www.ofgem.gov.uk/information-consumers/energy-advice-households/getting-extra-help-priority-services-register"), ("NHS 111", "https://111.nhs.uk/")]),

dict(slug="the-family-meeting-point", cat="Planning", mins=4, title="The family<br>meeting point", plain="The family meeting point",
    summary="Two places, one out-of-area contact, and the card everyone carries.",
    lede="The plan fits on a card. Two meeting points, one phone number outside the area, and who collects whom from school. Fifteen minutes at the kitchen table, then it lives in every bag's document pouch and you never think about it again.",
    checked="Checked against gov.uk Prepare guidance",
    sections=[
        ("Two", "places", "Near and far", [
            "<strong>Near:</strong> somewhere outside the house you can all reach on foot in five minutes, for a fire or a gas leak. The lamp post on the corner, the bus stop, a neighbour's gate. Not the car; the car may be the problem.",
            "<strong>Far:</strong> somewhere outside the area, for a flood or an evacuation. A relative or friend on higher ground, with room for the family and the pets. Ask them this week; write their address on the card.",
            "Walk to both with the children and let them lead the way back.",
            "Agree the rule: if we are separated, go to the near point and wait; if the near point is unsafe, go to the far one; if neither, ring the out-of-area contact."]),
        ("One", "number", "The out-of-area contact", [
            "Local lines jam in a local emergency; a call to another city often gets through. Choose one person outside your area as the message board: everyone rings them, they pass on who is safe and where.",
            "Everyone learns the number, including children old enough to dial. It is the one number on the card to know by heart.",
            "Text first, call second. A text gets through on a signal a call won't.",
            "Tell that person what you have agreed, and send them a copy of the card."]),
        ("Who", "collects whom", "School, nursery, work", [
            "Write down who collects each child from school and nursery if the parents cannot, and tell the school. Schools release children only to named adults.",
            "If one parent works far away, the plan says the other goes to the children first, and the far parent goes to the far point, not home.",
            "Pets: who is nearest to the house and can get the carriers. The Scout bag by the door makes that a thirty-second job.",
            "Review the card when the clocks change, with the bag check. Numbers move; children change schools."])],
    never=("Never", "Never plan to meet 'at home' after an evacuation, and never make the plan depend on one phone being charged. Paper, two places, one number."),
    after=None,
    frombag=[("#2a2a2a", "Document pouch:", "the family plan card, contacts card, cash, paper map"), ("#D0202E", "Recruit name window:", "the child's copy of the photo card and your number"), ("#ededed", "Lid pocket:", "the pen, for the cards")],
    numbers=[("Life at risk", "999"), ("Non-emergency police", "101"), ("Your out-of-area contact", "on the card"), ("Emergency Alerts", "gov.uk/alerts")],
    cta=("unit", "The Unit, £449", "Comes with the family plan card: meeting points, contacts, local map."),
    next=["teaching-your-child-the-bag", "the-72-hour-list-explained", "cyber-outage-cards-cash-and-comms"],
    sources=[("Prepare: get ready for emergencies, gov.uk", "https://prepare.campaign.gov.uk/"), ("Emergency Alerts, gov.uk", "https://www.gov.uk/alerts")]),

dict(slug="pets-in-an-emergency", cat="Family", mins=4, title="Pets in<br>an emergency", plain="Pets in an emergency",
    summary="Carriers by the door, three days of food, and which rest centres take animals.",
    lede="People go back into floods and fires for their pets. The way to stop that is to make leaving with the animal the easy option: a carrier by the door, a bag that clips onto yours, and a relative who will have you both.",
    checked="Checked against RSPCA and gov.uk guidance",
    sections=[
        ("Today", "once", "Make leaving with them easy", [
            "Keep the cat carrier where you can reach it in the dark, not in the loft. Keep the dog's lead on the hook by the door, and the Scout bag under it.",
            "Microchip details: check they are up to date today. It is the law for dogs and, in England, for cats. The pet card in the Scout's window carries the number, the vet and a photo.",
            "Ask your council now whether its rest centres take animals; many do, some don't. Then make the real plan a friend or relative who will take you and the animal, and write them on the family plan card.",
            "Fill the Scout's canister with three days of their own food from the bag you already buy, and swap it every three months. A sudden change of food is one more upset you don't need."]),
        ("Leaving", "in a hurry", "Them first, then the bag", [
            "Cats hide when frightened. Shut the doors to the rooms they hide in as soon as a warning comes, and get them into the carrier early, before the sirens.",
            "Dogs: lead on, then the Scout clipped onto the front of your Operator. The soft muzzle in the dog kit goes on if the dog is hurt or panicking; vets will ask for it.",
            "Water from the pet's own pouches, in the collapsible bowl, at every stop. Dogs overheat and dehydrate faster than people.",
            "At the rest centre or the relative's, the familiar blanket from the grey pouch and a quiet corner do more than anything else."]),
        ("If", "you can't take them", "Never leave them locked in", [
            "If you truly cannot take an animal, leave it loose in the house with food and water, not shut in a crate or a room that may flood. Put a note on the door saying what is inside, and ring the RSPCA.",
            "Never leave an animal in a car. Not in a flood, not in a heatwave, not for an hour.",
            "Flood water is as poisonous to pets as to people. Dry and wash a dog that has been in it before it licks its coat.",
            "When you are back, check paws, coat and appetite, and call the vet if anything is off. Then restock the Scout."])],
    never=("Never", "Never go back into a flood, a fire or a storm for a pet. Make the plan so you never have to choose."),
    after=None,
    frombag=[("#5c6a3a", "Olive pouch:", "water pouches, bowls, their food canister"), ("#2a2a2a", "Black pouch:", "lead, spare collar with ID tag, poo bags, wipes"), ("#2f7d4a", "Green pouch:", "pet first aid, the muzzle in the dog kit"), ("#6b6b6b", "Grey pouch:", "towel and the blanket that smells of home")],
    numbers=[("RSPCA cruelty and advice line", "0300 1234 999"), ("Your vet", "on the pet card"), ("Life at risk", "999"), ("Floodline", "0345 988 1188")],
    cta=("scout", "The Scout, £99", "Water, bowls, lead, clean-up, pet first aid and an ID tag, in a bag that clips onto yours."),
    next=["flooding-before-during-after", "the-family-meeting-point", "heatwave-and-cold-snap"],
    sources=[("Get your dog or cat microchipped, gov.uk", "https://www.gov.uk/get-your-dog-cat-microchipped"), ("RSPCA advice and welfare", "https://www.rspca.org.uk/adviceandwelfare"), ("Prepare: get ready for emergencies, gov.uk", "https://prepare.campaign.gov.uk/")]),

dict(slug="heatwave-and-cold-snap", cat="Weather", mins=5, title="Heatwave and<br>cold snap", plain="Heatwave and cold snap",
    summary="One room warm, one room cool, and who to check on in the street.",
    lede="The weather that kills most people in Britain is not the storm; it is the quiet week of heat or cold that follows. Both have the same answer: one room, kept right, and a knock on the door of whoever lives alone.",
    checked="Checked against UK Health Security Agency, Met Office and NHS guidance",
    sections=[
        ("Heat", "amber or red alert", "Shade, water, the vulnerable", [
            "Stay out of the sun between 11 and 3, and keep the house cool: curtains closed on the sunny side by day, windows open at night when the air outside is cooler than inside.",
            "Drink before you are thirsty, water over alcohol, and eat salty food. Babies, older people and anyone on diuretics or heart medicines dehydrate fastest.",
            "Pick the coolest room, usually north-facing or downstairs, and spend the hottest hours there. A damp cloth on the neck and a bowl of water for the feet beat a fan in a hot room.",
            "Never leave a person or an animal in a parked car. Check on neighbours who live alone twice a day, and ring 111 if anyone is confused, has stopped sweating, or cannot keep water down. Heatstroke is 999."]),
        ("Cold", "amber or red alert", "One warm room, layers, and the boiler", [
            "Heat the rooms you use to at least 18 degrees if anyone in the house is older, very young, or unwell, and sleep in the warmest room. Shut the doors and close the curtains at dusk.",
            "Layers beat one thick jumper; a hat indoors is not a joke. The grey pouch's hand warmers, beanie, gloves and foil blanket are for the night the boiler fails.",
            "Hot food and hot drinks through the day. Keep moving; an hour sitting still in a cold room drops your temperature faster than the walk to the shop.",
            "If the heating is off for a night, follow the power-cut guide: one room, hand warmers, foil over the fleece, never a camping stove or barbecue indoors. Carbon monoxide kills more people in cold snaps than the cold does."]),
        ("Both", "every time", "Who to check on", [
            "Make a list of the people in your street who live alone, are over 75, or have a child under one. Knock, don't ring; a phone going unanswered tells you nothing.",
            "Ask three things: are you warm or cool enough, have you eaten and drunk today, do you have your medicines. Then tell them you'll be back tomorrow.",
            "If someone is too hot, too cold, confused or not making sense, that is 111 for advice and 999 if they are drowsy or cannot be woken.",
            "Register anyone vulnerable with the Priority Services Register, so the network and the water company know to check on them in a cut."])],
    never=("Never", "Never heat a room with a gas hob, a barbecue, a generator or a patio heater, and never seal a room with a flame in it. Warmth with no air is how carbon monoxide gets you."),
    after=None,
    frombag=[("#6b6b6b", "Grey pouch:", "hand warmers, beanie and gloves, foil blanket, bivvy bag"), ("#5c6a3a", "Olive pouch:", "water, electrolytes and glucose from the comfort pack"), ("#ededed", "Lid pocket:", "radio for the alert level, torch for the night")],
    numbers=[("Urgent health", "111"), ("Life at risk", "999"), ("Power cut", "105"), ("Smell gas", "0800 111 999")],
    cta=("operator", "The Operator, £199", "Warmth for the night the boiler fails, water and electrolytes for the week it doesn't rain."),
    next=["power-cut-the-first-hour", "water-treating-storing-rationing", "medication-and-medical-devices"],
    sources=[("Beat the heat: hot weather advice, gov.uk", "https://www.gov.uk/government/publications/beat-the-heat-hot-weather-advice"), ("Keep warm, keep well, NHS", "https://www.nhs.uk/live-well/seasonal-health/keep-warm-keep-well/"), ("UK weather warnings, Met Office", "https://www.metoffice.gov.uk/weather/warnings-and-advice/uk-warnings")]),

dict(slug="the-72-hour-list-explained", cat="Planning", mins=8, title="The 72-hour list,<br>explained", plain="The 72-hour list, explained",
    summary="The Government's advice line by line, and the gap between a bag and a home.",
    lede="The Government's Prepare campaign asks every household to be able to look after itself for three days, and in October 2026 its Be Ready push asked again, louder. The list is short and sensible. Here it is, line by line, with what is already in your bag and what you still need to put in the cupboard.",
    checked="Checked against gov.uk Prepare guidance",
    sections=[
        ("The list", "line by line", "What the Government says, and where it is", [
            "<strong>Bottled water.</strong> About 2.5 to 3 litres a person a day to drink; 10 litres a day is 'most comfortable' with cooking and washing. The bag: the first day's pouches and the means to treat 50 litres more. The cupboard: the rest. See the water guide.",
            "<strong>Non-perishable food for three days, and a tin opener.</strong> The bag: two 2,325-calorie rations with a 15-year date, vegan and made without nut ingredients. The cupboard: tins and dried food you already eat, rotated. The Unit has the tin opener.",
            "<strong>A battery or wind-up torch, and a battery or wind-up radio.</strong> The bag: the head torch with 10-year lithium cells, and the crank-and-solar radio in the lid. Nothing to buy.",
            "<strong>A portable power bank and spare batteries.</strong> The bag: 10,000 mAh in the Operator, 20,000 in the Unit, with cables. Charge them every three months; the rotation card reminds you.",
            "<strong>A first aid kit, hand sanitiser and wet wipes.</strong> The bag: a BS 8599-1 kit, a trauma dressing, masks and gloves, sanitiser and wipes. The cupboard: your own regular medicines, see the medication guide.",
            "<strong>Baby supplies and pet supplies.</strong> The Cub and the Scout exist because the list is right: ready-to-feed formula so you don't need to boil water, nappies, and three days of the animal's own food."]),
        ("The gaps", "a bag can't fill", "What belongs in the house", [
            "Water in volume: the bag is the walk, the house is the store. Three days for four people is 30 litres to drink. Keep it under the stairs with the date written on.",
            "Warmth at home: blankets, a sleeping bag per person, and a way to heat one room safely. The bag's foil and bivvy are for outside.",
            "Copies of important documents, in the bag's pouch and in the cloud. Insurance numbers, prescriptions, the children's details.",
            "Know how to turn off the gas, the electricity and the water. Label the switches. Sign up for flood warnings and keep Emergency Alerts switched on on your phone."]),
        ("The plan", "the list doesn't print", "People, not things", [
            "Two meeting points and an out-of-area contact, on the family plan card. See the meeting point guide.",
            "Who in your street lives alone, and who checks on them. The Priority Services Register for anyone vulnerable.",
            "A child who has opened the bag before, and knows the whistle. Ten minutes, see the child's guide.",
            "A date in the diary when the clocks change: check the batteries, the water dates, the medicines, the phone numbers. The bag's rotation card and our reminders do the remembering."])],
    never=None,
    after=("The honest line", "A go bag is not a stockpile. It is the first day, carried, and the means to make the next two safe. The cupboard is the rest, and the plan on the card is the part that matters most. Buy the bag for the walk; fill the cupboard for the wait."),
    frombag=[("#5c6a3a", "Olive pouch:", "water pouches, tablets, rations, comfort pack"), ("#ededed", "Lid pocket:", "torch, radio, power bank, batteries, cards"), ("#2f7d4a", "Green pouch:", "first aid, masks, gloves, your medication pouch"), ("#2a2a2a", "Document pouch:", "copies, cash, contacts, map")],
    numbers=[("Life at risk", "999"), ("Power cut", "105"), ("Floodline", "0345 988 1188"), ("Emergency Alerts", "gov.uk/alerts")],
    cta=("operator", "The Operator, £199", "The Government's list, packed, in four pouches and a lid, with 20 litres left for yours."),
    next=["water-treating-storing-rationing", "the-family-meeting-point", "medication-and-medical-devices"],
    sources=[("Prepare: get ready for emergencies, gov.uk", "https://prepare.campaign.gov.uk/"), ("Emergency Alerts, gov.uk", "https://www.gov.uk/alerts"), ("Sign up for flood warnings, gov.uk", "https://www.gov.uk/sign-up-for-flood-warnings")]),
]

